<?php $pageTitle='Dashboard Executivo'; require_once __DIR__.'/includes/header.php';
$kpis=[];$kpis['clientes']=$pdo->query('SELECT COUNT(*) FROM clientes')->fetchColumn();$kpis['produtos']=$pdo->query('SELECT COUNT(*) FROM produtos')->fetchColumn();$kpis['estoque']=$pdo->query('SELECT COALESCE(SUM(estoque_atual*preco_custo),0) FROM produtos')->fetchColumn();$kpis['vendas']=$pdo->query("SELECT COALESCE(SUM(total),0) FROM vendas WHERE MONTH(data_venda)=MONTH(CURDATE()) AND YEAR(data_venda)=YEAR(CURDATE())")->fetchColumn();
$receber=$pdo->query("SELECT COALESCE(SUM(valor),0) FROM financeiro WHERE tipo='RECEITA' AND status='PENDENTE'")->fetchColumn();$pagar=$pdo->query("SELECT COALESCE(SUM(valor),0) FROM financeiro WHERE tipo='DESPESA' AND status='PENDENTE'")->fetchColumn();
$recentes=$pdo->query('SELECT v.id,v.data_venda,v.total,c.nome cliente,v.status FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id ORDER BY v.id DESC LIMIT 6')->fetchAll();
?><div class="row g-3 mb-4"><?php foreach([['Clientes',$kpis['clientes'],'bi-people'],['Produtos',$kpis['produtos'],'bi-box'],['Estoque valorizado',money($kpis['estoque']),'bi-boxes'],['Vendas no mês',money($kpis['vendas']),'bi-graph-up-arrow']] as $k):?><div class="col-md-6 col-xl-3"><div class="metric-card"><div><span><?=$k[0]?></span><strong><?=$k[1]?></strong></div><i class="bi <?=$k[2]?>"></i></div></div><?php endforeach;?></div>
<div class="row g-3"><div class="col-lg-8"><div class="panel"><div class="panel-title"><h3>Últimas vendas</h3><a href="modules/vendas/index.php">Ver todas</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>#</th><th>Cliente</th><th>Data</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($recentes as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['cliente']??'Consumidor final')?></td><td><?=date('d/m/Y H:i',strtotime($r['data_venda']))?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-4"><div class="panel mb-3"><div class="panel-title"><h3>Financeiro</h3></div><div class="finance-row"><span>A receber</span><strong><?=money($receber)?></strong></div><div class="finance-row"><span>A pagar</span><strong><?=money($pagar)?></strong></div><div class="finance-row total"><span>Saldo projetado</span><strong><?=money($receber-$pagar)?></strong></div></div><div class="panel"><h3>Atalhos</h3><div class="quick-grid"><a href="modules/vendas/index.php?action=novo">Nova venda</a><a href="modules/compras/index.php?action=novo">Nova compra</a><a href="modules/produtos/index.php?action=novo">Novo produto</a><a href="modules/financeiro/index.php?action=novo">Novo lançamento</a></div></div></div></div><?php require __DIR__.'/includes/footer.php'; ?>